const toolGuidance={
  'compress-pdf':{use:'Useful when a PDF is too large for email, an application portal or cloud upload. Image-heavy and scanned PDFs usually have more room to shrink than text-only documents.',expect:'Compression can downsample or recompress embedded images. Stronger settings usually create smaller files but can soften photographs and scans, so verify the result before replacing the original.',tip:'Keep the original PDF until you have checked small text, charts and images in the compressed copy.'},
  'merge-pdf':{use:'Combine reports, invoices, forms or chapters that belong in one document instead of sending several separate PDFs.',expect:'The files are joined in the order you select them. The tool does not rewrite the source documents before combining them.',tip:'Arrange your files in the intended reading order before uploading them.'},
  'split-pdf':{use:'Break a multi-page PDF into individual page PDFs when different pages need to be shared, filed or edited separately.',expect:'Each page becomes its own PDF and the pages are packaged together in a ZIP download.',tip:'Use Extract PDF Pages instead when you want several selected pages kept together in one new PDF.'},
  'pdf-to-jpg':{use:'Create JPG copies of PDF pages for previews, thumbnails, image-only workflows or systems that do not accept PDF.',expect:'Each PDF page is rendered as a JPG image at a practical web resolution and multiple pages are delivered in a ZIP file.',tip:'JPG is lossy and best for photographic or general-purpose sharing. Use PDF to PNG when sharper lossless page images matter more than file size.'},
  'pdf-to-png':{use:'Turn PDF pages into PNG images for screenshots, graphics, diagrams or workflows where lossless image output is preferred.',expect:'Every page is rendered to a PNG image. Multi-page documents are returned as a ZIP archive.',tip:'PNG files can be much larger than JPG for photographic pages, so choose JPG if small size matters more than lossless output.'},
  'jpg-to-pdf':{use:'Bundle scans, receipts, photos or photographed pages into a single PDF that is easier to share or archive.',expect:'Each selected JPG becomes a page in the output PDF, following the order supplied to the converter.',tip:'For document photos, crop and rotate the images first so the final PDF reads naturally.'},
  'png-to-pdf':{use:'Package PNG screenshots, diagrams or transparent graphics into a PDF for sharing, printing or submission.',expect:'Each PNG is placed on a PDF page. Transparency may be flattened by the PDF rendering workflow.',tip:'Use the images at their final orientation before conversion for the cleanest document.'},
  'rotate-pdf':{use:'Fix pages that were scanned or exported sideways or upside down without rebuilding the document.',expect:'Every page in the uploaded PDF is rotated by the selected angle. Page content is preserved rather than converted to images.',tip:'If only a few pages need changing, extract those pages first or use a desktop PDF editor for mixed rotations.'},
  'extract-pdf-pages':{use:'Create a smaller PDF containing only selected pages, such as a chapter, invoice section or pages required for a form submission.',expect:'Page ranges such as 1-3,5 are copied into a new PDF in their original order.',tip:'Double-check page numbers against the PDF viewer because printed page labels can differ from the file’s actual page index.'},
  'delete-pdf-pages':{use:'Remove unwanted blank pages, cover sheets or confidential pages before sharing a PDF copy.',expect:'All pages except the selected deletion range are written to a new PDF. The original upload is not overwritten.',tip:'Open the finished PDF and confirm the remaining pages before sharing it.'},
  'compress-image':{use:'Reduce image weight for websites, email, forms or messaging while keeping the same general format and dimensions.',expect:'The image is re-encoded with the selected quality and metadata is stripped. Visible quality loss depends on the source and chosen setting.',tip:'For websites, consider converting photographic PNG or JPG files to WebP after compression for additional savings.'},
  'resize-image':{use:'Change pixel dimensions for profile photos, web layouts, forms or content systems that require a maximum width.',expect:'The selected width is applied while the aspect ratio is preserved automatically. The image is not stretched.',tip:'Resize from the original source rather than repeatedly resizing an already reduced copy.'},
  'reduce-image-size':{use:'Aim for a practical KB target when an upload form or email limit rejects a large JPG or WebP image.',expect:'The converter tries progressively lower quality levels and returns the closest practical result it can produce. Exact target size is not guaranteed.',tip:'If the result is still too large, reduce image dimensions as well as compression quality.'},
  'jpg-to-png':{use:'Convert a JPG into PNG for software compatibility, lossless future edits or workflows that specifically require PNG.',expect:'The existing JPG pixels are wrapped in PNG encoding. Converting does not restore detail already lost through JPG compression.',tip:'Do not expect a smaller file: PNG is often larger than JPG for photographs.'},
  'png-to-jpg':{use:'Create a smaller, widely compatible JPG from a PNG when transparency is not required.',expect:'Transparent areas are placed on a white background and the image is encoded as JPG.',tip:'Keep the PNG original when transparency or pixel-perfect lossless graphics are important.'},
  'webp-to-png':{use:'Convert WebP graphics to PNG for older software, editing workflows or services that do not accept WebP.',expect:'The output is a PNG image. Transparency is preserved when supported by the source.',tip:'PNG may be significantly larger than WebP, so keep WebP for web delivery when compatibility is not a problem.'},
  'png-to-webp':{use:'Prepare PNG images for faster web delivery while retaining support for transparency.',expect:'The PNG is re-encoded as WebP with a balanced quality setting and metadata removed.',tip:'Compare the output visually before replacing important source graphics, especially artwork with fine gradients.'},
  'jpg-to-webp':{use:'Make photographic JPG assets more web-friendly for product pages, blogs and other bandwidth-sensitive pages.',expect:'The image is converted to WebP using a balanced lossy quality setting and metadata is removed.',tip:'Keep the original JPG as your source asset and serve the WebP copy where browser compatibility permits.'},
  'heic-to-jpg':{use:'Make HEIC or HEIF photos easier to upload, email or open in applications that expect JPG.',expect:'The HEIC image is decoded and re-encoded as a broadly compatible JPG. Some metadata may not be carried into the new file.',tip:'Keep the HEIC original if you may need its original metadata, color information or highest-quality source later.'},
  'remove-image-metadata':{use:'Create a sharing copy without common EXIF and ancillary metadata such as camera details or embedded location information.',expect:'The image pixels are retained while metadata is stripped where the underlying format and encoder allow it.',tip:'Metadata removal reduces accidental disclosure, but it is not a substitute for checking the visible content of the image itself.'},
  'compress-video':{use:'Reduce a video for email, messaging, web upload or storage while keeping a widely compatible MP4 result.',expect:'Without a target size, the video uses quality-based H.264 compression. With a target MB value, bitrate is estimated from duration, so the final size can vary.',tip:'Shorter clips and lower resolution are easier to compress aggressively without obvious quality loss.'},
  'mov-to-mp4':{use:'Convert camera or editing-tool MOV files to an MP4 that works across more browsers, phones and upload systems.',expect:'Video is encoded to H.264 with AAC audio for broad compatibility rather than simply renaming the file.',tip:'Because this is a transcode, keep the MOV original for editing or archival quality.'},
  'webm-to-mp4':{use:'Prepare a WebM video for devices, presentation software or services that prefer MP4.',expect:'The video is transcoded to H.264 video and AAC audio inside an MP4 container.',tip:'Transcoding takes more time than changing a filename because the media streams are actually re-encoded.'},
  'mp4-to-webm':{use:'Create a WebM version for browser-first video delivery or applications that prefer open web media formats.',expect:'The MP4 is transcoded to VP9 video with Opus audio. Encoding can take longer than H.264 conversion.',tip:'Test playback in your target browser or platform before removing the MP4 fallback.'},
  'mp4-to-gif':{use:'Turn a short MP4 clip into a looping animation for simple embeds, demos or places where GIF is specifically required.',expect:'GIF does not contain audio and can become very large for long or high-resolution clips. This tool reduces frame rate and width to keep output practical.',tip:'For modern websites, MP4 or WebM is usually much smaller than GIF for the same animation.'},
  'extract-audio':{use:'Create an MP3 copy of the soundtrack from a video you own, such as a recorded lecture, interview or personal clip.',expect:'The video stream is discarded and the audio is encoded to MP3. If the source has no usable audio track, conversion will fail.',tip:'Only extract audio from media you own or have permission to process.'},
  'resize-video':{use:'Reduce or standardize video width for web embeds, social editing workflows or smaller delivery files.',expect:'The chosen width is applied while aspect ratio is preserved and the result is encoded as H.264 MP4 with AAC audio.',tip:'Reducing resolution can lower file size, but bitrate and duration still strongly affect the final size.'},
  'mp3-to-wav':{use:'Create uncompressed PCM audio for editing applications, production workflows or software that requires WAV.',expect:'MP3 is decoded to 16-bit PCM WAV. The file will usually become much larger, and lost MP3 detail cannot be restored.',tip:'Use WAV as an editing/interchange copy rather than expecting it to improve the original MP3 quality.'},
  'wav-to-mp3':{use:'Make a large WAV recording easier to share, store or upload while retaining good listening quality.',expect:'The WAV is encoded to MP3 using a high-quality variable setting. The result is lossy but typically much smaller.',tip:'Keep the WAV master when you plan further editing or mastering.'},
  'm4a-to-mp3':{use:'Convert M4A or AAC audio for players, editing tools or platforms that specifically require MP3.',expect:'The audio is decoded and re-encoded as MP3, so this is a lossy-to-lossy conversion when the source is AAC.',tip:'Avoid repeated conversions between lossy formats when sound quality is important.'},
  'compress-audio':{use:'Reduce spoken-word or music file size for sharing by encoding it as MP3 at a chosen bitrate.',expect:'Lower bitrates create smaller files but can introduce more audible artifacts, especially in music and complex audio.',tip:'For speech, 64–96 kbps can be practical; music usually benefits from a higher bitrate.'},
  'word-to-pdf':{use:'Create a fixed-layout PDF copy of a DOC or DOCX file for sharing, printing or submission.',expect:'LibreOffice renders the document to PDF. Fonts, fields or advanced Microsoft Office features can differ from the original application.',tip:'Review page breaks, fonts, tables and headers in the resulting PDF before an important submission.'},
  'excel-to-pdf':{use:'Turn an XLS or XLSX workbook into a PDF for review, printing or read-only distribution.',expect:'LibreOffice renders workbook sheets to PDF according to spreadsheet print settings. Very wide sheets may span pages.',tip:'Set print areas, orientation and scaling in the spreadsheet first when presentation matters.'},
  'powerpoint-to-pdf':{use:'Create a PDF copy of PPT or PPTX slides for easy sharing when recipients do not need animations or editing.',expect:'Slides are rendered to static PDF pages. Animations, transitions, video and interactive elements are not preserved as live presentation features.',tip:'Check fonts and slide layout after conversion, especially when the deck uses fonts unavailable on the server.'}
};

const toolByPath=new Map(tools.map(t=>[`/${t.cat}/${t.slug}`,t]));
const toolBySlug=new Map(tools.map(t=>[t.slug,t]));

const guides={
  'webp-vs-png':{title:'WebP vs PNG: which format should you use?',desc:'A practical guide to choosing between WebP and PNG for websites, screenshots and transparent images.',body:`<p>WebP and PNG solve overlapping but different problems. PNG is a long-established lossless format with excellent transparency support. WebP supports transparency too, but usually creates much smaller files for web delivery.</p><h2>Use WebP for most website images</h2><p>If page speed matters, WebP is normally the better delivery format for photographs, product images and many interface assets. Smaller files reduce bandwidth and can improve loading performance, especially on mobile connections.</p><h2>Use PNG when lossless editing matters</h2><p>PNG is still useful for source assets, screenshots, technical graphics and workflows where you want predictable lossless output. It is also a safe choice when another application does not accept WebP.</p><h2>Keep an original</h2><p>Conversion can discard metadata or change compression. Keep your original file separately, then create optimized copies for the destination where they will be used.</p>`},
  'how-pdf-compression-works':{title:'How PDF compression works',desc:'Understand why PDFs become smaller and what can affect document quality.',body:`<p>PDF files can contain text, vector graphics, embedded fonts and large raster images. Compression reduces the space used by some of those components while keeping the document readable.</p><h2>Images usually matter most</h2><p>Scanned documents and image-heavy reports often shrink significantly because images can be resampled or recompressed. Text-only PDFs may change much less.</p><h2>Choose the right balance</h2><p>Strong compression is useful when an upload portal or email imposes a strict size limit. Light compression is better when print quality matters. Always open the result and check small text, charts and photographs before replacing the original.</p>`},
  'mp4-vs-webm':{title:'MP4 vs WebM for video',desc:'Compare MP4 and WebM compatibility, file size and common web use cases.',body:`<p>MP4 is the safest general-purpose delivery format because it has broad support across phones, browsers, editing applications and messaging platforms. WebM is designed for efficient web media and is especially useful in modern browser-based experiences.</p><h2>Choose MP4 for compatibility</h2><p>When you are sending a file to another person or uploading to a service with unknown requirements, MP4 using H.264 video and AAC audio is usually the safest choice.</p><h2>Choose WebM for web-first workflows</h2><p>WebM can be a strong option for browser playback and modern web applications. Always test the target service before deleting the original.</p>`},
  'safe-file-conversion':{title:'How to convert files safely online',desc:'Simple privacy and security checks before uploading files to an online converter.',body:`<p>Before uploading a file, check whether it contains sensitive information and whether the service explains storage and deletion clearly. For confidential material, prefer local processing or an approved organizational workflow.</p><h2>Check retention and access</h2><p>A converter should explain how long temporary files are kept and whether download links expire. Avoid services that publish predictable file URLs or make uploads publicly browsable.</p><h2>Keep originals</h2><p>Conversion can change metadata, formatting, color profiles or compression quality. Keep the source file until you have verified the result.</p>`},
  'heic-to-jpg-guide':{title:'Why convert HEIC photos to JPG?',desc:'When HEIC is useful, when JPG is easier, and what changes during conversion.',body:`<p>HEIC can store high-quality photos efficiently and is common on modern Apple devices. The problem appears when older software, forms or websites expect JPG.</p><h2>JPG is easier to share</h2><p>JPG is supported almost everywhere, making it a practical compatibility format for uploads, email attachments and systems that reject HEIC.</p><h2>Conversion is not magic</h2><p>Changing formats can alter metadata and apply new compression. Keep the HEIC original if you may want to edit or archive the highest-quality source later.</p>`},
  'video-compression-guide':{title:'How to make a video file smaller',desc:'Understand resolution, bitrate, codec and audio settings before compressing video.',body:`<p>Video size is driven mainly by duration and bitrate. Resolution matters because larger frames usually need more bitrate to look good. Audio also contributes to the final size.</p><h2>Target the destination</h2><p>If you only need to fit under an upload limit, reduce bitrate first and avoid unnecessary resolution changes. If the video is much larger than the display area, resizing can save additional space.</p><h2>Expect a quality trade-off</h2><p>Lossy compression removes information. A sensible workflow keeps the original and creates a smaller delivery copy for email, messaging or web use.</p>`}
};

function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function canonical(path){return path==='/' ? `${SITE_URL}/` : `${SITE_URL}${path}`;}
function jsonLd(obj){return `<script type="application/ld+json">${JSON.stringify(obj).replace(/</g,'\\u003c')}</script>`;}
function adsenseVerificationMeta(){return ADSENSE_PUBLISHER_VALID?`<meta name="google-adsense-account" content="${esc(process.env.ADSENSE_PUBLISHER_ID)}">`:'';}
function adsHead(){return ADS_CONFIGURED?`<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${esc(process.env.ADSENSE_PUBLISHER_ID)}" crossorigin="anonymous"></script>`:'';}
function adSlot(){return ADS_CONFIGURED?`<div class="adslot" aria-label="Advertisement"><ins class="adsbygoogle" style="display:block;width:100%" data-ad-client="${esc(process.env.ADSENSE_PUBLISHER_ID)}" data-ad-slot="${esc(process.env.ADSENSE_SLOT_CONTENT)}" data-ad-format="auto" data-full-width-responsive="true"></ins></div><script>(adsbygoogle=window.adsbygoogle||[]).push({});</script>`:'';}
function glyph(cat){const labels={pdf:'PDF',image:'IMG',video:'VID',audio:'AUD',document:'DOC'};return `<span class="toolGlyph ${cat}">${labels[cat]||'FILE'}</span>`;}
function nav(){return `<header class="topbar"><div class="wrap nav"><a class="brand" href="/" aria-label="${esc(SITE_NAME)} home"><span class="brandmark">F</span><span>${esc(SITE_NAME)}</span></a><nav class="navlinks" aria-label="Main navigation"><a href="/compress/">Compress</a><a href="/convert/">Convert</a><a href="/tools/">All Tools</a><a href="/guides/">Guides</a></nav><button class="menuBtn" aria-label="Open menu" aria-controls="mobile-nav" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button></div><nav class="mobileNav wrap" id="mobile-nav" aria-label="Mobile navigation"><a href="/compress/">Compress</a><a href="/convert/">Convert</a><a href="/tools/">All Tools</a><a href="/guides/">Guides</a></nav></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footerGrid"><div class="footerIntro"><a class="brand footerBrand" href="/"><span class="brandmark">F</span><span>${esc(SITE_NAME)}</span></a><p>Everyday tools for PDFs, images, video, audio and documents. Choose a task, upload your file and download the result.</p></div><div><h4>Popular tools</h4><a href="/image/compress-image">Compress Image</a><a href="/pdf/compress-pdf">Compress PDF</a><a href="/video/compress-video">Compress Video</a><a href="/image/heic-to-jpg">HEIC to JPG</a><a href="/pdf/merge-pdf">Merge PDF</a></div><div><h4>Explore</h4><a href="/tools/">All Tools</a><a href="/pdf/">PDF Tools</a><a href="/image/">Image Tools</a><a href="/video/">Video Tools</a><a href="/audio/">Audio Tools</a><a href="/document/">Document Tools</a></div><div><h4>Trust & legal</h4><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><a href="/cookie-policy/">Cookie Policy</a><a href="/copyright/">Copyright & Takedown</a><a href="/acceptable-use/">Acceptable Use</a><a href="/security/">Security & Retention</a><a href="/formats/">Supported Formats</a></div></div><div class="copyright"><span>© ${new Date().getFullYear()} ${esc(SITE_NAME)}.</span><span>Use only files you own or have permission to process.</span></div></div></footer>`;}

function layout({title,desc,path='/',body,noindex=false,adAllowed=false,schema=[]}){if(!noindex)schema=[{'@context':'https://schema.org','@type':'WebSite','@id':canonical('/')+'#website',name:SITE_NAME,url:canonical('/'),inLanguage:'en'},...schema];const full=path==='/'?`${SITE_NAME} — ${title}`:`${title} | ${SITE_NAME}`;return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(full)}</title><meta name="description" content="${esc(desc)}">${noindex?'':`<link rel="canonical" href="${esc(canonical(path))}">`}${noindex?'<meta name="robots" content="noindex,nofollow,noarchive">':'<meta name="robots" content="index,follow,max-image-preview:large">'}<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="alternate icon" href="/favicon.ico"><link rel="apple-touch-icon" href="/favicon.png"><meta name="theme-color" content="#5b5cf0"><meta property="og:type" content="website"><meta property="og:title" content="${esc(full)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${esc(canonical(path))}"><meta name="twitter:card" content="summary">${noindex?'':adsenseVerificationMeta()}<link rel="stylesheet" href="/styles.css">${adAllowed?adsHead():''}${schema.map(jsonLd).join('')}</head><body><a class="skipLink" href="#main-content">Skip to content</a>${nav()}<main id="main-content" tabindex="-1">${body}</main>${footer()}<script src="/app.js" defer></script></body></html>`;}
function categoryCards(){return Object.entries(categoryMeta).map(([k,v])=>`<a class="categoryCard" href="/${k}/">${glyph(k)}<div><h3>${v.name}</h3><p>${v.desc}</p></div><span class="arrow">→</span></a>`).join('');}
function toolCards(list,compact=false){return list.map(t=>`<a class="toolCard${compact?' compact':''}" href="/${t.cat}/${t.slug}" data-search="${esc((t.title+' '+t.desc+' '+t.ext.join(' ')).toLowerCase())}">${glyph(t.cat)}<div class="toolCardCopy"><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p></div><span class="arrow">→</span></a>`).join('');}
function home(){const searchCards=tools.map(t=>`<a class="searchResult" href="/${t.cat}/${t.slug}" data-search-item data-search="${esc((t.title+' '+t.desc+' '+t.ext.join(' ')).toLowerCase())}">${glyph(t.cat)}<span><b>${esc(t.title)}</b><small>${esc(t.desc)}</small></span><span class="arrow" aria-hidden="true">→</span></a>`).join('');const body=`
<section class="homeHero"><div class="wrap heroInner">
<p class="eyebrow">Your everyday file toolbox</p>
<h1>Convert and compress files.<br><span>Keep it simple.</span></h1>
<p class="heroDescription">Convert, compress and organize your files.<br> PDFs, images, video, audio and documents, all in one place.</p>
<div class="searchArea"><label class="srOnly" for="tool-search">Find a file tool</label><div class="heroSearch"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m21 21-4.35-4.35m1.35-5.65a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z"/></svg><input id="tool-search" type="search" placeholder="Find a tool, e.g. PDF to JPG" data-tool-search autocomplete="off" aria-controls="tool-search-results"><kbd aria-hidden="true">/</kbd></div><div class="searchResults" id="tool-search-results" data-search-results hidden>${searchCards}<p class="searchEmpty" data-search-empty hidden>No matching tools. Try a file type such as PDF, image or video, or <a href="/tools/">browse all tools</a>.</p></div><span class="srOnly" role="status" data-search-status></span></div>
<div class="heroTrust"><span>No account needed</span><span>Up to ${Math.round(MAX_UPLOAD/1024/1024)} MB per upload</span><a href="/security/">Temporary file storage ↗</a></div>
</div></section>
<section class="section homeTasks"><div class="wrap"><div class="sectionHead"><div><h2>What do you need to do?</h2><p>A few useful places to start.</p></div><a class="textLink" href="/tools/">All ${tools.length} tools <span aria-hidden="true">→</span></a></div><div class="toolGrid">${toolCards(['compress-pdf','compress-image','merge-pdf','heic-to-jpg','compress-video','convert-image','convert-video','office-to-pdf'].map(slug=>toolBySlug.get(slug)).filter(Boolean),true)}</div></div></section>
<section class="homeCategories softSection"><div class="wrap"><div class="sectionHead"><div><h2>Browse by file type</h2><p>Find the right tool for the file you have.</p></div></div><div class="categoryGrid">${categoryCards()}</div></div></section>
<section class="section"><div class="wrap homeNotes"><div><h2>Three steps. Then you’re done.</h2><p>Choose your tool and upload a file. Adjust the settings if needed, then download your result. Keep the original until you’ve checked the new file.</p><a class="textLink" href="/guides/">Read the file guides <span aria-hidden="true">→</span></a></div><div><h2>Your files stay yours.</h2><p>Uploads are processed on our server in temporary jobs. Files are scheduled for deletion after ${Math.round(RETENTION_MS/60000)} minutes and are never published in a public gallery.</p><a class="textLink" href="/security/">How we handle your files <span aria-hidden="true">→</span></a></div></div></section>`;return layout({title:'Free File Converter & Compressor',desc:'Convert and compress PDF, image, video, audio and document files with a fast, privacy-focused interface.',path:'/',body});}
function toolsHub(){const body=`<section class="hubHero"><div class="wrap"><div class="hubHeader"><span class="sectionKicker">Toolbox</span><h1>All File Tools</h1><p>Find the exact tool you need. Each page has one job and clearly lists the formats it accepts.</p></div><div class="tabs"><a class="pill active" href="/tools/">All</a>${Object.entries(categoryMeta).map(([k,v])=>`<a class="pill" href="/${k}/">${v.name}</a>`).join('')}</div><div class="toolGrid">${toolCards(tools)}</div></div></section>`;return layout({title:'All File Tools',desc:'Browse PDF, image, video, audio and document conversion and compression tools.',path:'/tools/',body});}
function catHub(cat){const m=categoryMeta[cat], list=tools.filter(t=>t.cat===cat);const body=`<section class="hubHero"><div class="wrap"><div class="crumb"><a href="/">Home</a><span>›</span>${m.name}</div><div class="hubHeader categoryHeader">${glyph(cat)}<div><span class="sectionKicker">${m.name}</span><h1>${m.name}</h1><p>${m.desc}</p></div></div><div class="toolGrid">${toolCards(list)}</div><section class="hubContent"><h2>Choose the exact task</h2><p>Choose a tool above to see its supported formats and settings. Keep your original file, and check the result before sharing it: conversion can change quality, formatting or metadata.</p></section></div></section>`;return layout({title:m.name,desc:m.desc,path:`/${cat}/`,body});}
function taskHub(kind){const list=kind==='compress'?tools.filter(t=>/compress|reduce/.test(t.slug)):tools.filter(t=>/\bto\b/.test(t.title.toLowerCase())||t.slug.includes('-to-')||['extract-audio','convert-image','convert-video','convert-audio','office-to-pdf'].includes(t.slug));const title=kind==='compress'?'Compress Files':'Convert Files';const body=`<section class="hubHero"><div class="wrap"><div class="crumb"><a href="/">Home</a><span>›</span>${title}</div><div class="hubHeader"><span class="sectionKicker">${kind==='compress'?'Smaller files':'Change formats'}</span><h1>${title}</h1><p>${kind==='compress'?'Reduce image, PDF, video and audio sizes with task-specific controls.':'Choose the exact source and destination workflow instead of guessing settings.'}</p></div><div class="toolGrid">${toolCards(list)}</div></div></section>`;return layout({title,desc:`${title} with focused, privacy-conscious online tools.`,path:`/${kind}/`,body});}
function fieldHtml(f,idx=0){const [name,label,type,val]=f;if(type==='select')return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${val.map((v,i)=>`<option value="${esc(v)}"${i===0?' selected':''}>${esc(v.replace(/-/g,' '))}</option>`).join('')}</select></div>`;return `<div class="field"><label for="${name}">${label}</label><div class="inputShell"><input id="${name}" name="${name}" type="${type}" ${val?`placeholder="${esc(val)}"`:''} ${type==='number'?'min="1"':''}></div></div>`;}
const guideTools={
  'webp-vs-png':['png-to-webp','jpg-to-webp','webp-to-png'],
  'how-pdf-compression-works':['compress-pdf'],
  'mp4-vs-webm':['convert-video','mp4-to-webm','webm-to-mp4'],
  'safe-file-conversion':[],
  'heic-to-jpg-guide':['heic-to-jpg'],
  'video-compression-guide':['compress-video','resize-video']
};
function helpfulGuides(tool){const matches=Object.entries(guideTools).filter(([,slugs])=>slugs.includes(tool.slug)).map(([slug])=>slug);if(!matches.length)matches.push('safe-file-conversion');return `<p class="guideLinks">Helpful reading: ${matches.map(slug=>`<a href="/guides/${slug}">${esc(guides[slug].title)}</a>`).join(' · ')}</p>`;}
function related(tool){return tools.filter(t=>t.cat===tool.cat&&t.slug!==tool.slug).slice(0,6);}
function formatSummary(exts){const names=exts.map(x=>x.slice(1).toUpperCase());return names.length<=7?names.join(' · '):`${names.slice(0,7).join(' · ')} · +${names.length-7} more`;}
function formatChips(exts){const names=exts.map(x=>x.slice(1).toUpperCase());const first=names.slice(0,8).map(x=>`<span>${esc(x)}</span>`).join('');const rest=names.length>8?`<details class="formatsMore"><summary>+${names.length-8} more</summary><div>${names.slice(8).map(x=>`<span>${esc(x)}</span>`).join('')}</div></details>`:'';return `<div class="formatChips">${first}${rest}</div>`;}
function presets(tool){if(tool.slug==='compress-image')return `<div class="optionGroup"><span class="fieldLabel">Compression</span><label class="choiceCard"><input type="radio" name="quality" value="82" checked><span><b>Recommended</b><small>Balanced quality and file size</small></span></label><label class="choiceCard"><input type="radio" name="quality" value="65"><span><b>Smaller file</b><small>Stronger compression for sharing</small></span></label><label class="choiceCard"><input type="radio" name="quality" value="92"><span><b>High quality</b><small>Lighter compression</small></span></label><a class="exactSizeLink" href="/image/reduce-image-size">Need a target file size? →</a></div><details class="advanced"><summary>Advanced settings</summary><div class="advancedInner">${fieldHtml(['output','Output format','select',['auto','webp','jpg','png']])}</div></details>`;
if(tool.slug==='compress-pdf')return `<div class="optionGroup"><span class="fieldLabel">Compression level</span><label class="choiceCard"><input type="radio" name="level" value="balanced" checked><span><b>Recommended</b><small>Good balance for everyday documents</small></span></label><label class="choiceCard"><input type="radio" name="level" value="strong"><span><b>Strong</b><small>Smaller PDF, more image compression</small></span></label><label class="choiceCard"><input type="radio" name="level" value="light"><span><b>Light</b><small>Prioritize visual quality</small></span></label></div>`;
if(tool.slug==='compress-audio')return `<div class="optionGroup"><span class="fieldLabel">Audio quality</span><label class="choiceCard"><input type="radio" name="bitrate" value="128k" checked><span><b>High quality</b><small>128 kbps MP3</small></span></label><label class="choiceCard"><input type="radio" name="bitrate" value="96k"><span><b>Balanced</b><small>96 kbps MP3</small></span></label><label class="choiceCard"><input type="radio" name="bitrate" value="64k"><span><b>Small file</b><small>64 kbps MP3</small></span></label></div>`;
return (tool.fields||[]).length?`<div class="settingsGrid">${tool.fields.map(fieldHtml).join('')}</div>`:'';}
function contentFaq(tool){const cat=categoryMeta[tool.cat].name.replace(' Tools','').toLowerCase();return [
[`Is ${tool.title} free to use?`,`${tool.title} is free to use without creating an account. Upload up to ${Math.round(MAX_UPLOAD/1024/1024)} MB in one request, with a maximum of 30 files. Request limits apply to protect server capacity.`],
[`Which files can I upload?`,`This page accepts ${formatSummary(tool.ext)}. A damaged, encrypted or unusually encoded file can still fail even when its extension is supported.`],
[`Will my original file be changed?`,`No. The original stays on your device. The server creates a separate temporary output file for you to download.`],
[`How long are uploaded files kept?`,`Uploaded files and results are scheduled for deletion after ${Math.round(RETENTION_MS/60000)} minutes. Download your result before the link expires. Files are processed on our server and are not published in a public gallery.`],
[`Can I use this on a phone?`,`Yes. The interface is responsive and the upload workflow is designed for modern mobile browsers as well as desktop.`],
[`Does conversion always preserve everything?`,`Not always. ${cat} formats can contain metadata, codecs, fonts, color profiles or advanced features that may change during conversion or compression. Keep your original until you verify the result.`]
];}
function commonTargets(tool){if(tool.slug==='compress-image'||tool.slug==='reduce-image-size')return `<section class="contentSection"><div class="contentSectionHead"><span class="sectionKicker">Common targets</span><h2>Choose a size based on where the image is going</h2><p>Exact limits vary by service. Treat these as practical examples rather than universal platform rules.</p></div><div class="targetTable"><div><b>Under 250 KB</b><span>Forms, thumbnails, lightweight web use</span></div><div><b>Under 500 KB</b><span>General web uploads and email</span></div><div><b>Under 1 MB</b><span>Good-quality sharing and websites</span></div><div><b>Under 2 MB</b><span>Higher-detail photos</span></div></div></section>`;
if(tool.slug==='compress-video')return `<section class="contentSection"><div class="contentSectionHead"><span class="sectionKicker">File-size planning</span><h2>Target size depends on duration and bitrate</h2><p>Long videos need a lower bitrate to fit the same MB target. If visual quality drops too far, reduce the clip length or resolution instead of forcing an unrealistic size.</p></div></section>`;
return '';}
function toolPage(tool){const path=`/${tool.cat}/${tool.slug}`;const accept=tool.ext.join(',');const guide=toolGuidance[tool.slug]||{use:tool.desc,expect:'The converter creates a new output file and leaves your original on your device unchanged.',tip:'Keep the source file until you have verified the result.'};const faqs=contentFaq(tool);const body=`<section class="toolTop"><div class="wrap toolWrap"><div class="crumb"><a href="/">Home</a><span>›</span><a href="/${tool.cat}/">${categoryMeta[tool.cat].name}</a><span>›</span>${esc(tool.title)}</div><div class="toolHeading"><span class="categoryLabel">${categoryMeta[tool.cat].name}</span><h1>${esc(tool.title)}</h1><p>${esc(tool.desc)}</p></div><div class="toolPanel newToolPanel"><form data-processing method="post" action="/process/${tool.slug}" enctype="multipart/form-data"><div class="dropzone" data-dropzone><div class="uploadVisual"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M5 15.5A4.5 4.5 0 0 0 9.5 20h7a3.5 3.5 0 0 0 .6-6.95A6 6 0 0 0 5.6 12"/></svg></div><h2>Drop files here</h2><p>or</p><input class="fileInput" id="files-${tool.slug}" type="file" name="files" accept="${accept}" multiple required><label class="btn uploadLabel" for="files-${tool.slug}">Choose files</label>${tool.cat==='image'?`<button class="pasteBtn" type="button" data-paste-file data-target="files-${tool.slug}">Paste image</button>`:''}<div class="fileName" aria-live="polite"></div><p class="uploadLimit">Up to ${Math.round(MAX_UPLOAD/1024/1024)} MB per request · Single or bulk upload (up to 30 files)</p></div><div class="supportedBlock"><span>Supported</span>${formatChips(tool.ext)}</div>${presets(tool)}<button class="btn submit" type="submit">${esc(tool.title)}</button></form></div><div class="trustBar"><span>No account needed</span><a href="/security/">Deletion scheduled after ${Math.round(RETENTION_MS/60000)} min</a><a href="/formats/">Supported formats</a></div></div></section><section class="seoContent"><div class="wrap contentWrap"><section class="contentIntro"><div><span class="sectionKicker">${esc(tool.title)}</span><h2>What to expect</h2><p>${esc(guide.use)}</p><p>${esc(guide.expect)}</p></div><aside class="contentTip"><h3>Before you start</h3><p>${esc(guide.tip)}</p>${helpfulGuides(tool)}</aside></section><div class="adBoundary">${adSlot()}</div>${commonTargets(tool)}<section class="contentSection stepsSection"><div class="contentSectionHead centered"><span class="sectionKicker">Simple workflow</span><h2>How to ${esc(tool.title.toLowerCase())}</h2></div><div class="steps"><article><span>1</span><h3>Upload</h3><p>Select a file or multiple files from your device${tool.cat==='image'?' or paste an image from your clipboard':''}.</p></article><article><span>2</span><h3>Choose settings</h3><p>Use the recommended preset or adjust the options when the task needs more control.</p></article><article><span>3</span><h3>Process</h3><p>The server creates the result inside a temporary private job.</p></article><article><span>4</span><h3>Download</h3><p>Check the result before replacing or deleting your original file.</p></article></div></section><section class="contentSection privacySplit"><div><span class="sectionKicker">Privacy by design</span><h2>Your files, handled with care</h2><p>Your files are uploaded to our server for processing. Download links are temporary and files are not listed publicly. For confidential documents, use an offline tool or a service approved by your organization.</p><a class="textLink" href="/security/">Security & retention details →</a></div><div class="privacyPoints"><div><b>Temporary storage</b><span>Scheduled deletion after ${Math.round(RETENTION_MS/60000)} minutes</span></div><div><b>No public gallery</b><span>Your upload is not published as a searchable page</span></div><div><b>Keep your original</b><span>Compression and conversion can change quality or metadata</span></div></div></section><section class="contentSection faqSection"><div class="contentSectionHead centered"><span class="sectionKicker">Questions</span><h2>${esc(tool.title)} FAQ</h2></div><div class="faqList">${faqs.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></section><section class="contentSection relatedSection"><div class="sectionHead"><div><span class="sectionKicker">Keep working</span><h2>Related ${categoryMeta[tool.cat].name}</h2></div><a class="textLink" href="/${tool.cat}/">View category →</a></div><div class="toolGrid">${toolCards(related(tool),true)}</div></section></div></section>`;
const schema=[{'@context':'https://schema.org','@type':'SoftwareApplication',name:tool.title,applicationCategory:'UtilitiesApplication',operatingSystem:'Any',description:tool.desc,url:canonical(path),offers:{'@type':'Offer',price:'0',priceCurrency:'USD'}},{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:canonical('/')},{'@type':'ListItem',position:2,name:categoryMeta[tool.cat].name,item:canonical(`/${tool.cat}/`)},{'@type':'ListItem',position:3,name:tool.title,item:canonical(path)}]}];return layout({title:tool.title+' Online',desc:tool.desc+' No account needed. Upload up to '+Math.round(MAX_UPLOAD/1024/1024)+' MB per request.',path,body,adAllowed:true,schema});}
function guidesHub(){const cards=Object.entries(guides).map(([slug,g])=>`<a class="card" href="/guides/${slug}"><div class="icon" aria-hidden="true">↗</div><h3>${esc(g.title)}</h3><p>${esc(g.desc)}</p></a>`).join('');const body=`<section class="hubHero"><div class="wrap"><h1>Guides & File Tips</h1><p>Original explanations that help you choose formats, understand compression and protect your files.</p><div class="guideGrid" style="margin-top:24px">${cards}</div></div></section>`;return layout({title:'Guides & File Tips',desc:'Practical guides to file formats, compression, conversion and safe online processing.',path:'/guides/',body});}
function guidePage(slug,g){const path=`/guides/${slug}`;const body=`<section class="hubHero"><div class="wrap" style="max-width:820px"><div class="crumb"><a href="/">Home</a> › <a href="/guides/">Guides</a> › ${esc(g.title)}</div><h1>${esc(g.title)}</h1><p>${esc(g.desc)}</p><article class="content">${g.body}<aside class="notice"><h2>Put this guide to use</h2>${(guideTools[slug]||[]).length?`<ul>${guideTools[slug].map(key=>{const t=toolBySlug.get(key);return `<li><a href="/${t.cat}/${t.slug}">${esc(t.title)}</a> — ${esc(t.desc)}</li>`;}).join('')}</ul>`:`<p>Review <a href="/security/">how temporary files are stored and deleted</a>, check <a href="/formats/">supported formats</a>, or <a href="/tools/">choose a file tool</a>.</p>`}</aside></article></div></section>`;return layout({title:g.title,desc:g.desc,path,body,schema:[{'@context':'https://schema.org','@type':'Article',headline:g.title,description:g.desc,mainEntityOfPage:canonical(path),isPartOf:{'@id':canonical('/')+'#website'},inLanguage:'en'}]});}
const legal={
  about:['About '+SITE_NAME,`<p>${esc(SITE_NAME)} provides ${tools.length} online tools for converting, compressing and preparing PDFs, images, video, audio and office documents. You can use the tools without creating an account.</p><h2>Choose a tool for your task</h2><p>Start with the <a href="/tools/">tool directory</a>, or browse <a href="/compress/">compression tools</a> to make files smaller and <a href="/convert/">conversion tools</a> to change formats. Each tool lists the files it accepts and explains the settings and limitations.</p><h2>What happens to your files</h2><p>Files are uploaded to our server for processing. Temporary jobs are scheduled for deletion after ${Math.round(RETENTION_MS/60000)} minutes. Your original stays on your device. Read our <a href="/security/">storage and retention information</a> before uploading confidential material.</p><h2>Check the result</h2><p>Conversion can change image quality, formatting or metadata. Keep the original until you have checked the output. Our <a href="/guides/">file guides</a> explain common choices and trade-offs. The service processes user-supplied files; it does not download content from streaming platforms.</p><p>For questions, accessibility feedback or a problem with a tool, see <a href="/contact/">Contact</a>.</p>`],
  contact:['Contact Us',`<p>Questions, accessibility feedback, privacy requests or copyright concerns can be sent to <a href="mailto:${esc(CONTACT_EMAIL)}"><b>${esc(CONTACT_EMAIL)}</b></a>.</p><h2>Reporting a problem</h2><p>Include the tool name or page address, your browser, the input file format and the error message. For an accessibility issue, describe the step you could not complete and any assistive technology you used.</p><p>Please do not send uploaded files, private download links or confidential information. A description of the problem is enough to start.</p><p>You can also check the <a href="/formats/">supported formats</a> and <a href="/security/">file retention information</a>.</p>`],
  privacy:['Privacy Policy',`<p>This policy explains how ${SITE_NAME} handles information when you use the site.</p><h2>Uploaded files</h2><p>Files are used to perform the conversion or compression you request. They are stored in temporary job directories, are not published as public pages, and are scheduled for automatic deletion after ${Math.round(RETENTION_MS/60000)} minutes. Download any result you want to keep before its link expires.</p><h2>Technical data</h2><p>The server may process ordinary request metadata needed for security and delivery, such as IP address, user agent, timestamps and error information. Application logging is designed not to include uploaded filenames.</p><h2>Advertising and cookies</h2><p>Advertising is disabled unless the site owner has deliberately completed the required configuration. If Google AdSense is enabled, Google and its partners may use cookies or other identifiers as described in Google's advertising policies. For the EEA, UK and Switzerland, ads must not be enabled until a Google-certified consent management platform is configured.</p><h2>Analytics</h2><p>No analytics product is enabled by default in this package. If analytics is added later, it should record tool events without sending uploaded filenames or file contents.</p><h2>Contact</h2><p>Privacy questions: <a href="mailto:${esc(CONTACT_EMAIL)}">${esc(CONTACT_EMAIL)}</a>.</p>`],
  'cookie-policy':['Cookie Policy',`<p>The base deployment does not set advertising cookies because AdSense is disabled by default. Essential server behavior may use short-lived technical state only when required for a request.</p><h2>If advertising is enabled</h2><p>The site owner must configure a Google-certified CMP for users in the EEA, UK and Switzerland before enabling AdSense. The consent interface and vendor disclosures should be maintained through the selected certified CMP.</p>`],
  terms:['Terms of Use',`<p>By using ${SITE_NAME}, you agree to upload only content you own or are authorized to process. You are responsible for confirming that converted files are suitable for your intended use.</p><h2>No warranty of perfect conversion</h2><p>File formats can contain uncommon codecs, encryption, corruption or features that a converter cannot preserve. Keep the original file until you have verified the output.</p><h2>Prohibited use</h2><p>Do not use the service to distribute malware, infringe intellectual property rights, bypass access controls, process unlawful content, attack systems or overload the service.</p>`],
  copyright:['Copyright & Takedown Policy',`<p>${SITE_NAME} is designed for user-supplied files and does not create public libraries of uploaded content. Users must have the rights or permission needed to process a file.</p><h2>Copyright concerns</h2><p>If you believe material associated with this service infringes your rights, contact <a href="mailto:${esc(CONTACT_EMAIL)}">${esc(CONTACT_EMAIL)}</a> with enough information to identify the issue. Temporary files may already have been automatically deleted by the time a request is received.</p>`],
  'acceptable-use':['Acceptable Use Policy',`<p>Do not upload or process malware, stolen data, content you are not authorized to use, or material for the purpose of evading platform access controls. Automated abuse, denial-of-service behavior and attempts to discover other users' temporary jobs are prohibited.</p><h2>Streaming-platform downloads</h2><p>This service does not provide YouTube, TikTok, Instagram or similar streaming/social-media downloaders. The platform is for files supplied directly by the user.</p>`],
  formats:['Supported Formats',`<p>These are the input format families supported by the tools. Availability depends on the conversion engines installed on the server. A damaged file, encrypted file, or unusual internal codec can still fail even when the extension is listed.</p><h2>Images</h2><p><b>${IMAGE_INPUTS.map(x=>x.slice(1).toUpperCase()).join(', ')}</b></p><p>The universal image converter exports JPG, PNG or WebP. HEIC, HEIF and AVIF inputs are normalized through libheif before image processing.</p><h2>Video</h2><p><b>${VIDEO_INPUTS.map(x=>x.slice(1).toUpperCase()).join(', ')}</b></p><p>The universal video converter exports MP4 or WebM using FFmpeg.</p><h2>Audio</h2><p><b>${AUDIO_INPUTS.map(x=>x.slice(1).toUpperCase()).join(', ')}</b></p><p>The universal audio converter exports MP3 or WAV using FFmpeg.</p><h2>Office documents</h2><p><b>${[...WORD_INPUTS,...SHEET_INPUTS,...SLIDE_INPUTS].map(x=>x.slice(1).toUpperCase()).join(', ')}</b></p><p>Office-compatible inputs are converted to PDF through headless LibreOffice.</p><h2>Why not literally every file format?</h2><p>There are thousands of proprietary, legacy and application-specific formats. ${SITE_NAME} only advertises formats that the production stack is intentionally configured to process. This avoids promising support that cannot be verified.</p>`],
  security:['Security & File Retention',`<p>Uploads are written into random per-job temporary directories. Public pages never expose a browsable uploads folder.</p><h2>Validation</h2><p>The server checks allowed extensions and inspects the detected MIME type. Processing commands are executed with argument arrays rather than shell interpolation. Optional ClamAV integration can be required in production.</p><h2>Downloads</h2><p>Download links require both a random job ID and a separate random token. Job and download responses carry noindex headers and are excluded from the sitemap.</p><h2>Deletion</h2><p>Jobs are scheduled for deletion after ${Math.round(RETENTION_MS/60000)} minutes. Production operators should additionally configure storage lifecycle rules when external object storage is used.</p>`]
};
const pageDescriptions={
 about:`Learn what ${SITE_NAME} does, which files the tools handle, and how temporary processing works before you upload.`,
 contact:`Contact ${SITE_NAME} about file conversion, accessibility, privacy or copyright. Learn which details to include when reporting a tool problem.`,
 privacy:`How ${SITE_NAME} handles uploaded files, temporary storage, technical request data and advertising. Read the privacy policy before uploading.`,
 'cookie-policy':`Read how cookies and advertising consent are handled on ${SITE_NAME}, including what changes when advertising is enabled.`,
 terms:`Read the terms for using ${SITE_NAME} file tools, including permitted uploads, conversion limitations and your responsibility to check results.`,
 copyright:`How to report a copyright concern to ${SITE_NAME} and what to know about user-supplied files and temporary storage.`,
 'acceptable-use':`Understand permitted file processing on ${SITE_NAME} and restrictions on malware, unauthorized content and automated abuse.`,
 formats:`Check supported PDF, image, video, audio and office formats, available outputs and compatibility limitations before choosing a file tool.`,
 security:`How ${SITE_NAME} validates uploads, protects temporary download links and schedules file deletion after ${Math.round(RETENTION_MS/60000)} minutes.`
};
function legalPage(slug,data){const [title,content]=data;const body=`<section class="hubHero"><div class="wrap" style="max-width:850px"><div class="crumb"><a href="/">Home</a> › ${esc(title)}</div><h1>${esc(title)}</h1><article class="content">${content}</article></div></section>`;return layout({title,desc:pageDescriptions[slug],path:`/${slug}/`,body,adAllowed:false});}

function redirect(res,target){res.writeHead(301,{'location':target,'cache-control':'public, max-age=3600'});res.end();}
function send(res,status,html,headers={},method='GET'){const security={'content-type':'text/html; charset=utf-8','x-content-type-options':'nosniff','x-frame-options':'SAMEORIGIN','cross-origin-resource-policy':'same-origin','referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()','content-security-policy':"default-src 'self'; img-src 'self' data: https:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://*.googlesyndication.com https://*.doubleclick.net https://*.google.com https://*.gstatic.com; frame-src https://*.googlesyndication.com https://*.doubleclick.net https://*.google.com; connect-src 'self' https://*.googlesyndication.com https://*.doubleclick.net https://*.google.com; object-src 'none'; base-uri 'self'; form-action 'self'"};if(SITE_URL.startsWith('https://'))security['strict-transport-security']='max-age=31536000; includeSubDomains';if(method==='HEAD'){res.writeHead(status,{...security,...headers});return res.end();}res.writeHead(status,{...security,...headers});res.end(html);}
async function serveStatic(req,res,path){const p=join(ROOT,'public',path.slice(1));try{const data=await readFile(p);const type=path.endsWith('.css')?'text/css; charset=utf-8':path.endsWith('.js')?'application/javascript; charset=utf-8':path.endsWith('.svg')?'image/svg+xml':path.endsWith('.ico')?'image/x-icon':path.endsWith('.png')?'image/png':'application/octet-stream';res.writeHead(200,{'content-type':type,'cache-control':'public,max-age=86400','x-content-type-options':'nosniff'});if(req.method==='HEAD')return res.end();res.end(data);}catch{send(res,404,notFound(),{},req.method);}}
function notFound(){return layout({title:'Page Not Found',desc:'The requested page could not be found.',path:'/',noindex:true,body:`<div class="result"><div class="ok">🔎</div><h1>Page not found</h1><p>Try the full tool directory instead.</p><a class="btn" href="/tools/">Browse tools</a></div>`});}


function run(cmd,args,{cwd=ROOT,timeout=120000}={}){return new Promise((resolveRun,reject)=>{let exe=cmd,a=args;if(process.platform==='win32'){const shim=join(ROOT,'bin',`${cmd.replace(/-/g,'_')}_shim.py`);if(existsSync(shim)){exe='python3';a=[shim,...args];}}const p=spawn(exe,a,{cwd,stdio:['ignore','pipe','pipe']});let out='',err='';const kill=setTimeout(()=>{p.kill('SIGKILL');reject(new Error('Processing timed out'));},timeout);p.stdout.on('data',d=>{if(out.length<100000)out+=d});p.stderr.on('data',d=>{if(err.length<100000)err+=d});p.on('error',e=>{clearTimeout(kill);reject(e)});p.on('close',code=>{clearTimeout(kill);if(code===0)resolveRun({out,err});else reject(new Error((err||out||`${cmd} failed`).slice(-1200)))});});}
async function commandExists(cmd){try{await run(process.platform==='win32'?'where':'which',[cmd],{timeout:5000});return true}catch{return false}}
async function runtimeStatus(){const entries=await Promise.all(RUNTIME_COMMANDS.map(async c=>[c,await commandExists(c)]));const imageMagick=(await commandExists('magick'))?'magick':((await commandExists('convert'))?'convert':null);let pythonPackages=false;try{await run('python3',['-c','import PIL, fitz'],{timeout:5000});pythonPackages=true}catch{}return {commands:Object.fromEntries(entries),imageMagick,pythonPackages};}
const RUNTIME_STATUS=await runtimeStatus();
const RUNTIME_READY=Object.values(RUNTIME_STATUS.commands).every(Boolean)&&Boolean(RUNTIME_STATUS.imageMagick)&&RUNTIME_STATUS.pythonPackages;
async function runMagick(args,options={}){if(!RUNTIME_STATUS.imageMagick)throw new Error('ImageMagick is unavailable');return run(RUNTIME_STATUS.imageMagick,args,options);}

async function parseMultipart(req){const ct=req.headers['content-type']||'';const bm=ct.match(/boundary=(?:"([^"]+)"|([^;]+))/);if(!bm)throw new Error('Invalid upload form');const boundary=Buffer.from(`--${bm[1]||bm[2]}`);const chunks=[];let size=0;for await(const c of req){size+=c.length;if(size>MAX_UPLOAD+2*1024*1024)throw new Error('Upload is too large');chunks.push(c)}const buf=Buffer.concat(chunks);const parts=[];let pos=0;while(true){const start=buf.indexOf(boundary,pos);if(start<0)break;let pstart=start+boundary.length;if(buf.slice(pstart,pstart+2).toString()==='--')break;if(buf.slice(pstart,pstart+2).toString()==='\r\n')pstart+=2;const next=buf.indexOf(boundary,pstart);if(next<0)break;let end=next;if(buf.slice(end-2,end).toString()==='\r\n')end-=2;const part=buf.slice(pstart,end);const sep=part.indexOf(Buffer.from('\r\n\r\n'));if(sep>0){const head=part.slice(0,sep).toString('utf8');const content=part.slice(sep+4);const dm=head.match(/content-disposition:\s*form-data;\s*name="([^"]+)"(?:;\s*filename="([^"]*)")?/i);if(dm)parts.push({name:dm[1],filename:dm[2]||null,content,headers:head});}pos=next;}const fields={};const files=[];for(const p of parts){if(p.filename){files.push(p)}else fields[p.name]=p.content.toString('utf8').trim();}return {fields,files};}
async function detectedMime(path){try{const {out}=await run('file',['-b','--mime-type',path],{timeout:5000});return out.trim()}catch{return 'application/octet-stream'}}
function mimeOkForExt(ext,mime){if(ext==='.pdf')return mime==='application/pdf';if(IMAGE_INPUTS.includes(ext))return mime.startsWith('image/')||mime==='application/octet-stream'||mime==='application/x-photoshop';if(VIDEO_INPUTS.includes(ext))return mime.startsWith('video/')||mime==='application/octet-stream'||mime==='application/vnd.rn-realmedia'||(['.ts','.mts'].includes(ext)&&mime==='text/plain');if(AUDIO_INPUTS.includes(ext))return mime.startsWith('audio/')||mime==='application/octet-stream'||mime==='application/ogg'||(ext==='.wma'&&mime==='video/x-ms-asf');if([...WORD_INPUTS,...SHEET_INPUTS,...SLIDE_INPUTS].includes(ext))return mime.startsWith('application/')||mime==='application/zip'||mime.startsWith('text/');return false;}

async function scan(path){if(!MALWARE_SCAN_ENABLED)return;const has=await commandExists('clamscan');if(!has)throw new Error('Malware scanning is enabled but clamscan is unavailable');try{await run('clamscan',['--no-summary',path],{timeout:30000});}catch(e){throw new Error('Malware scan failed or the file was rejected. Check ClamAV signatures and scanner health.');}}
async function saveUploads(tool,items,dir){if(!items.length)throw new Error('Choose at least one file');if(items.length>30)throw new Error('Too many files in one request (maximum 30)');const saved=[];for(let i=0;i<items.length;i++){const original=basename(items[i].filename||'upload');const ext=extname(original).toLowerCase();if(!tool.ext.includes(ext))throw new Error(`Unsupported file type: ${ext||'unknown'} (${original})`);const originalBase=basename(original,ext).replace(/[^a-zA-Z0-9._-]/g,'_')||`file-${i}`;const path=join(dir,`input-${i}-${originalBase}${ext}`);await writeFile(path,items[i].content,{mode:0o600});const mime=await detectedMime(path);const ok=mimeOkForExt(ext,mime);if(!ok)throw new Error(`File content of ${original} does not match the selected ${ext.slice(1).toUpperCase()} format`);await scan(path);saved.push({path,original,originalBase,ext});}return saved;}
async function zipFiles(dir,files,out){await run('zip',['-j','-q',out,...files],{cwd:dir,timeout:30000});}
async function ffprobeDuration(input){try{const {out}=await run('ffprobe',['-v','error','-show_entries','format=duration:stream=duration','-of','json',input]);const data=JSON.parse(out||'{}');const candidates=[data?.format?.duration,...(data?.streams||[]).map(x=>x.duration)].map(Number).filter(n=>Number.isFinite(n)&&n>0);return candidates.length?Math.max(...candidates):null;}catch{return null;}}

function safeImageOutputExt(input,requested='auto'){
  if(['webp','jpg','png'].includes(requested))return `.${requested}`;
  const ext=extname(input).toLowerCase();
  if(IMAGE_DIRECT_OUTPUTS.has(ext))return ext==='.jpeg'||ext==='.jfif'?'.jpg':ext;
  return '.webp';
}
async function prepareImageInput(input,dir){
  const ext=extname(input).toLowerCase();
  if(['.heic','.heif','.avif'].includes(ext)){
    const normalized=join(dir,`normalized-${newId(4)}.png`);
    await run('heif-convert',['-q','95',input,normalized],{timeout:60000});
    return normalized;
  }
  return input;
}
async function imageMagickInput(input,dir){
  const prepared=await prepareImageInput(input,dir);
  // Force ImageMagick to decode the file now so malformed/unsupported input fails early.
  await runMagick([prepared,'-ping','info:'],{timeout:30000});
  return prepared;
}
async function processSingle(tool,item,fields,dir,index=0){
  const input=item.path;
  let out;
  switch(tool.proc){
    case 'compressPdf':{out=join(dir,`compressed-${index}.pdf`);const map={light:'/printer',balanced:'/ebook',strong:'/screen'};await run('gs',['-sDEVICE=pdfwrite','-dCompatibilityLevel=1.4',`-dPDFSETTINGS=${map[fields.level]||'/ebook'}`,'-dNOPAUSE','-dQUIET','-dBATCH',`-sOutputFile=${out}`,input]);break;}
    case 'splitPdf':{const pattern=join(dir,`page-${index}-%d.pdf`);await run('pdfseparate',[input,pattern]);const parts=(await readdir(dir)).filter(x=>new RegExp(`^page-${index}-\\d+\\.pdf$`).test(x)).map(x=>join(dir,x));out=join(dir,`split-pages-${index}.zip`);await zipFiles(dir,parts,out);break;}
    case 'pdfToImage':{const prefix=join(dir,`page-${index}`);await run('pdftoppm',[tool.format==='jpg'?'-jpeg':'-png','-r','150',input,prefix]);const parts=(await readdir(dir)).filter(x=>x.startsWith(`page-${index}-`)&&x.endsWith(tool.format==='jpg'?'.jpg':'.png')).map(x=>join(dir,x));out=join(dir,`pdf-to-${tool.format}-${index}.zip`);await zipFiles(dir,parts,out);break;}
    case 'rotatePdf':{out=join(dir,`rotated-${index}.pdf`);await run('python3',[join(ROOT,'scripts/pdf_tools.py'),'rotate',input,out,fields.degrees||'90']);break;}
    case 'extractPdf':{out=join(dir,`extracted-pages-${index}.pdf`);await run('python3',[join(ROOT,'scripts/pdf_tools.py'),'extract',input,out,fields.pages||'1']);break;}
    case 'deletePdf':{out=join(dir,`pages-removed-${index}.pdf`);await run('python3',[join(ROOT,'scripts/pdf_tools.py'),'delete',input,out,fields.pages||'2']);break;}
    case 'compressImage':{const src=await imageMagickInput(input,dir);const e=safeImageOutputExt(input,fields.output||'auto');out=join(dir,`compressed-${index}${e}`);const q=String(Math.max(20,Math.min(95,Number(fields.quality)||75)));const args=[src];if(extname(input).toLowerCase()==='.gif'&&e==='.gif')args.push('-coalesce');args.push('-auto-orient','-strip');if(e==='.jpg')args.push('-background','white','-alpha','remove','-alpha','off');if(['.jpg','.webp','.tif','.tiff'].includes(e))args.push('-quality',q);if(e==='.gif')args.push('-layers','Optimize');args.push(out);await runMagick(args,{timeout:60000});break;}
    case 'resizeImage':{const src=await imageMagickInput(input,dir);const e=safeImageOutputExt(input,fields.output||'auto');out=join(dir,`resized-${index}${e}`);const w=Math.max(16,Math.min(10000,Number(fields.width)||1200));const args=[src];if(extname(input).toLowerCase()==='.gif'&&e==='.gif')args.push('-coalesce');args.push('-auto-orient','-resize',`${w}x`,'-strip');if(e==='.jpg')args.push('-background','white','-alpha','remove','-alpha','off');if(e==='.gif')args.push('-layers','Optimize');args.push(out);await runMagick(args,{timeout:60000});break;}
    case 'targetImage':{const src=await imageMagickInput(input,dir);const e=(fields.output==='jpg')?'.jpg':'.webp';out=join(dir,`reduced-${index}${e}`);const target=Math.max(20,Math.min(20000,Number(fields.targetKb)||500))*1024;let best=null;for(const q of [88,80,72,64,56,48,40,32,24,18]){const cand=join(dir,`candidate-${index}-${q}${e}`);const args=[src,'-auto-orient','-strip'];if(e==='.jpg')args.push('-background','white','-alpha','remove','-alpha','off');args.push('-quality',String(q),cand);await runMagick(args,{timeout:60000});const sz=(await stat(cand)).size;if(!best||Math.abs(sz-target)<Math.abs(best.size-target))best={path:cand,size:sz};if(sz<=target){best={path:cand,size:sz};break;}}await writeFile(out,await readFile(best.path));break;}
    case 'convertImageUniversal':{const src=await imageMagickInput(input,dir);const fmt=['webp','jpg','png'].includes(fields.output)?fields.output:'webp';out=join(dir,`converted-${index}.${fmt}`);const args=[src,'-auto-orient','-strip'];if(fmt==='jpg')args.push('-background','white','-alpha','remove','-alpha','off','-quality','90');if(fmt==='webp')args.push('-quality','82');args.push(out);await runMagick(args,{timeout:60000});break;}
    case 'convertImage':{out=join(dir,`converted-${index}.${tool.out}`);if(['.heic','.heif','.avif'].includes(extname(input).toLowerCase())&&tool.out==='jpg'){await run('heif-convert',['-q','90',input,out]);}else{const args=[input,'-auto-orient','-strip'];if(tool.out==='jpg')args.push('-background','white','-alpha','remove','-alpha','off','-quality','90');if(tool.out==='webp')args.push('-quality','82');args.push(out);await runMagick(args);}break;}
    case 'stripImage':{const src=await imageMagickInput(input,dir);const e=safeImageOutputExt(input,fields.output||'auto');out=join(dir,`metadata-removed-${index}${e}`);const args=[src];if(extname(input).toLowerCase()==='.gif'&&e==='.gif')args.push('-coalesce');args.push('-auto-orient','-strip');if(e==='.jpg')args.push('-background','white','-alpha','remove','-alpha','off');if(e==='.gif')args.push('-layers','Optimize');args.push(out);await runMagick(args,{timeout:60000});break;}
    case 'convertVideoUniversal':{const fmt=fields.output==='webm'?'webm':'mp4';out=join(dir,`converted-${index}.${fmt}`);if(fmt==='webm')await run('ffmpeg',['-y','-i',input,'-c:v','libvpx-vp9','-crf','34','-b:v','0','-c:a','libopus','-b:a','96k',out],{timeout:180000});else await run('ffmpeg',['-y','-i',input,'-c:v','libx264','-preset','medium','-crf','23','-c:a','aac','-b:a','128k','-movflags','+faststart',out],{timeout:180000});break;}
    case 'compressVideo':{out=join(dir,`compressed-${index}.mp4`);const target=Number(fields.targetMb);const dur=(Number.isFinite(target)&&target>0)?await ffprobeDuration(input):null;if(Number.isFinite(target)&&target>0&&dur){const total=Math.max(250000,(target*8*1024*1024)/dur);const audio=96000;const video=Math.max(150000,total-audio);await run('ffmpeg',['-y','-i',input,'-c:v','libx264','-preset','medium','-b:v',String(Math.floor(video)),'-maxrate',String(Math.floor(video*1.08)),'-bufsize',String(Math.floor(video*2)),'-c:a','aac','-b:a','96k','-movflags','+faststart',out],{timeout:180000});}else{await run('ffmpeg',['-y','-i',input,'-c:v','libx264','-preset','medium','-crf','28','-c:a','aac','-b:a','96k','-movflags','+faststart',out],{timeout:180000});}break;}
    case 'videoToMp4':{out=join(dir,`converted-${index}.mp4`);await run('ffmpeg',['-y','-i',input,'-c:v','libx264','-preset','medium','-crf','23','-c:a','aac','-b:a','128k','-movflags','+faststart',out],{timeout:180000});break;}
    case 'mp4ToWebm':{out=join(dir,`converted-${index}.webm`);await run('ffmpeg',['-y','-i',input,'-c:v','libvpx-vp9','-crf','34','-b:v','0','-c:a','libopus','-b:a','96k',out],{timeout:180000});break;}
    case 'mp4ToGif':{out=join(dir,`converted-${index}.gif`);await run('ffmpeg',['-y','-i',input,'-vf','fps=12,scale=720:-1:flags=lanczos',out],{timeout:180000});break;}
    case 'extractAudio':{out=join(dir,`audio-${index}.mp3`);await run('ffmpeg',['-y','-i',input,'-vn','-c:a','libmp3lame','-q:a','3',out],{timeout:180000});break;}
    case 'resizeVideo':{out=join(dir,`resized-${index}.mp4`);const w=Math.max(160,Math.min(3840,Number(fields.width)||1280));await run('ffmpeg',['-y','-i',input,'-vf',`scale=${w}:-2`,'-c:v','libx264','-crf','23','-preset','medium','-c:a','aac','-b:a','128k','-movflags','+faststart',out],{timeout:180000});break;}
    case 'convertAudioUniversal':{const fmt=fields.output==='wav'?'wav':'mp3';out=join(dir,`converted-${index}.${fmt}`);if(fmt==='wav')await run('ffmpeg',['-y','-i',input,'-vn','-c:a','pcm_s16le',out],{timeout:120000});else await run('ffmpeg',['-y','-i',input,'-vn','-c:a','libmp3lame','-q:a','2',out],{timeout:120000});break;}
    case 'audioConvert':{out=join(dir,`converted-${index}.${tool.out}`);if(tool.out==='wav')await run('ffmpeg',['-y','-i',input,'-c:a','pcm_s16le',out]);else await run('ffmpeg',['-y','-i',input,'-c:a','libmp3lame','-q:a','2',out]);break;}
    case 'compressAudio':{out=join(dir,`compressed-${index}.mp3`);const br=['128k','96k','64k'].includes(fields.bitrate)?fields.bitrate:'96k';await run('ffmpeg',['-y','-i',input,'-c:a','libmp3lame','-b:a',br,out]);break;}
    case 'officeToPdf':{const outdir=join(dir,`office-out-${index}`);await mkdir(outdir);const profile=`-env:UserInstallation=file://${join(dir,`lo-profile-${index}`)}`;await run('libreoffice',[profile,'--headless','--convert-to','pdf','--outdir',outdir,input],{timeout:120000});const ps=(await readdir(outdir)).filter(x=>x.toLowerCase().endsWith('.pdf'));if(!ps.length)throw new Error('Document conversion did not produce a PDF');out=join(outdir,ps[0]);break;}
    default: throw new Error('Unsupported processor');
  }
  return out;
}
async function processTool(tool,inputs,fields,dir){
  if(tool.proc==='mergePdf'||tool.proc==='imagesToPdf'){
    const out=join(dir,tool.proc==='mergePdf'?'merged.pdf':'images.pdf');
    if(tool.proc==='mergePdf')await run('pdfunite',[...inputs.map(x=>x.path),out]);
    else await run('python3',[join(ROOT,'scripts/pdf_tools.py'),'images_to_pdf',out,...inputs.map(x=>x.path)]);
    const s=await stat(out);if(!s.isFile()||s.size===0)throw new Error('Processing produced an empty file');
    return {out,name:basename(out),count:inputs.length};
  }

  if(inputs.length===1){
    const out=await processSingle(tool,inputs[0],fields,dir,0);
    const s=await stat(out);if(!s.isFile()||s.size===0)throw new Error('Processing produced an empty file');
    const outExt=extname(out);
    let downloadName = basename(out);
    if(downloadName.startsWith('compressed-')||downloadName.startsWith('resized-')||downloadName.startsWith('reduced-')||downloadName.startsWith('converted-')||downloadName.startsWith('metadata-removed-')){
      downloadName = `${inputs[0].originalBase}${outExt}`;
    }
    return {out,name:downloadName,count:1};
  }

  // Bulk processing (multiple files uploaded)
  const results=[];
  for(let i=0;i<inputs.length;i++){
    const subOut=await processSingle(tool,inputs[i],fields,dir,i);
    const s=await stat(subOut);
    if(s.isFile()&&s.size>0){
      const outExt=extname(subOut);
      const friendlyName=join(dir,`${inputs[i].originalBase}-${i+1}${outExt}`);
      if(friendlyName!==subOut){
        await writeFile(friendlyName,await readFile(subOut));
        results.push(friendlyName);
      } else {
        results.push(subOut);
      }
    }
  }
  if(!results.length)throw new Error('Bulk processing produced no files');
  const zipOut=join(dir,`${tool.slug}-bulk.zip`);
  await zipFiles(dir,results,zipOut);
  const s=await stat(zipOut);if(!s.isFile()||s.size===0)throw new Error('Creating bulk archive failed');
  return {out:zipOut,name:`${tool.slug}-bulk.zip`,count:results.length};
}

const jobs=new Map();
const rateBuckets=new Map();
let activeJobs=0;
function allowProcess(ip){const now=Date.now(),windowMs=10*60*1000;let b=rateBuckets.get(ip);if(!b||now-b.start>windowMs)b={start:now,count:0};b.count++;rateBuckets.set(ip,b);return b.count<=RATE_LIMIT_MAX;}
function newId(n=18){return randomBytes(n).toString('base64url')}
async function cleanup(){const now=Date.now();for(const [id,j] of jobs){if(now-j.created>RETENTION_MS){jobs.delete(id);await rm(j.dir,{recursive:true,force:true}).catch(()=>{});}}try{for(const name of await readdir(WORK_ROOT)){const p=join(WORK_ROOT,name);const s=await stat(p);if(now-s.mtimeMs>RETENTION_MS*2)await rm(p,{recursive:true,force:true});}}catch{}}
await cleanup();
setInterval(cleanup,10*60*1000).unref();

function resultPage(job,tool){const size=Math.max(1,Math.round(job.size/1024));const isZip=job.name.endsWith('.zip');const countText=job.count&&job.count>1?` (${job.count} files processed in bulk)`:'';const body=`<div class="result"><div class="ok">✅</div><h1>Your ${isZip?'archive':'file'} is ready</h1><p>${esc(tool.title)} completed successfully${countText}. This private result page contains no advertising.</p><div class="notice">Output size: <b>${size.toLocaleString()} KB</b> · This job is scheduled for automatic deletion.</div><a class="btn" href="/download/${job.id}?token=${encodeURIComponent(job.token)}">Download ${isZip?'ZIP archive':'result'}</a><p class="small" style="margin-top:18px"><a href="/${tool.cat}/${tool.slug}">← Process more files</a></p></div>`;return layout({title:'File Ready',desc:'Private file conversion result.',path:`/result/${job.id}`,body,noindex:true,adAllowed:false});}
async function handleProcess(req,res,tool){if(!RUNTIME_READY){const missing=Object.entries(RUNTIME_STATUS.commands).filter(([,ok])=>!ok).map(([k])=>k);if(!RUNTIME_STATUS.pythonPackages)missing.push('Python Pillow/PyMuPDF');if(!RUNTIME_STATUS.imageMagick)missing.push('ImageMagick (magick or convert)');return send(res,503,layout({title:'Converter Runtime Not Ready',desc:'Required conversion engines are missing.',noindex:true,body:`<div class="result"><h1>Converter runtime is incomplete</h1><p>This deployment is missing: ${esc(missing.join(', '))}. Deploy with the included Dockerfile or install the documented runtime packages.</p></div>`}),{'x-robots-tag':'noindex','cache-control':'no-store'});}if(activeJobs>=MAX_CONCURRENT_JOBS){return send(res,503,layout({title:'Server Busy',desc:'Too many conversion jobs are running.',noindex:true,body:`<div class="result"><h1>Server is busy</h1><p>Please retry shortly.</p></div>`}),{'retry-after':'15','x-robots-tag':'noindex'});}activeJobs++;const dir=join(WORK_ROOT,newId(12));await mkdir(dir,{recursive:true,mode:0o700});try{const {fields,files}=await parseMultipart(req);const inputs=await saveUploads(tool,files,dir);const {out,name,count}=await processTool(tool,inputs,fields,dir);const id=newId(),token=newId(24),s=await stat(out);const job={id,token,dir,path:out,size:s.size,created:Date.now(),name:name||basename(out),tool:tool.slug,count};jobs.set(id,job);send(res,200,resultPage(job,tool),{'x-robots-tag':'noindex, nofollow, noarchive','cache-control':'no-store'});}catch(e){await rm(dir,{recursive:true,force:true}).catch(()=>{});const body=`<div class="result"><div class="ok">⚠️</div><h1>We couldn't process that file</h1><div class="error">${esc(e.message||'Processing failed')}</div><p>Check the file format and settings, then try again.</p><a class="btn" href="/${tool.cat}/${tool.slug}">Back to ${esc(tool.title)}</a></div>`;send(res,400,layout({title:'Processing Error',desc:'Private processing error.',path:'/tools/',body,noindex:true}),{'x-robots-tag':'noindex, nofollow, noarchive','cache-control':'no-store'});}finally{activeJobs=Math.max(0,activeJobs-1);}}
async function handleDownload(req,res,id,url){const j=jobs.get(id);if(!j||url.searchParams.get('token')!==j.token){send(res,404,notFound(),{'x-robots-tag':'noindex, nofollow, noarchive','cache-control':'no-store'},req.method);return}try{await access(j.path);const s=await stat(j.path);const headers={'content-type':'application/octet-stream','content-length':s.size,'content-disposition':`attachment; filename="${j.name.replace(/[^a-zA-Z0-9._-]/g,'_')}"`,'cache-control':'no-store, private','x-robots-tag':'noindex, nofollow, noarchive','x-content-type-options':'nosniff'};res.writeHead(200,headers);if(req.method==='HEAD')return res.end();createReadStream(j.path).pipe(res);}catch{send(res,404,notFound(),{'x-robots-tag':'noindex'},req.method);}}
function robots(){return `User-agent: *\nAllow: /\nDisallow: /process/\nDisallow: /result/\nDisallow: /download/\nSitemap: ${SITE_URL}/sitemap.xml\n`;}
function sitemap(){const urls=['/','/tools/','/compress/','/convert/','/guides/',...Object.keys(categoryMeta).map(k=>`/${k}/`),...tools.map(t=>`/${t.cat}/${t.slug}`),...Object.keys(guides).map(g=>`/guides/${g}`),'/about/','/contact/','/privacy/','/cookie-policy/','/terms/','/copyright/','/acceptable-use/','/security/','/formats/'];return `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(u=>`<url><loc>${esc(canonical(u))}</loc></url>`).join('')}</urlset>`;}
function adsTxt(){const pub=process.env.ADSENSE_PUBLISHER_ID||'';if(!/^ca-pub-\d+$/.test(pub))return '# Configure ADSENSE_PUBLISHER_ID before publishing ads.txt\n';return `google.com, ${pub.replace('ca-','')}, DIRECT, f08c47fec0942fa0\n`;}

const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,SITE_URL);let p=url.pathname;if(p!=='/'&&p.endsWith('//'))p=p.replace(/\/+$/,'/');if(p==='/styles.css'||p==='/app.js'||p==='/favicon.svg'||p==='/favicon.ico'||p==='/favicon.png')return serveStatic(req,res,p);if(p==='/robots.txt'){res.writeHead(200,{'content-type':'text/plain; charset=utf-8'});if(req.method==='HEAD')return res.end();return res.end(robots())}if(p==='/sitemap.xml'){res.writeHead(200,{'content-type':'application/xml; charset=utf-8'});if(req.method==='HEAD')return res.end();return res.end(sitemap())}if(p==='/ads.txt'){res.writeHead(200,{'content-type':'text/plain; charset=utf-8'});if(req.method==='HEAD')return res.end();return res.end(adsTxt())}const isGetOrHead=req.method==='GET'||req.method==='HEAD';if(isGetOrHead&&p==='/healthz'){res.writeHead(RUNTIME_READY?200:503,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex'});if(req.method==='HEAD')return res.end();return res.end(JSON.stringify({ok:RUNTIME_READY,tools:tools.length,adsConfigured:ADS_CONFIGURED,runtime:RUNTIME_STATUS}))}if(isGetOrHead){const hubsWithSlash=['/tools','/compress','/convert','/guides',...Object.keys(categoryMeta).map(k=>`/${k}`),...Object.keys(legal).map(k=>`/${k}`)];if(hubsWithSlash.includes(p))return redirect(res,`${p}/`);if(p.endsWith('/')&&p!=='/'){const noSlash=p.slice(0,-1);if(toolByPath.has(noSlash)||(noSlash.startsWith('/guides/')&&guides[noSlash.slice(8)]))return redirect(res,noSlash);}}if(isGetOrHead&&p==='/')return send(res,200,home(),{},req.method);if(isGetOrHead&&p==='/tools/')return send(res,200,toolsHub(),{},req.method);if(isGetOrHead&&p==='/compress/')return send(res,200,taskHub('compress'),{},req.method);if(isGetOrHead&&p==='/convert/')return send(res,200,taskHub('convert'),{},req.method);if(isGetOrHead&&p==='/guides/')return send(res,200,guidesHub(),{},req.method);for(const cat of Object.keys(categoryMeta))if(isGetOrHead&&p===`/${cat}/`)return send(res,200,catHub(cat),{},req.method);if(isGetOrHead&&toolByPath.has(p))return send(res,200,toolPage(toolByPath.get(p)),{},req.method);const gm=p.match(/^\/guides\/([^/]+)$/);if(isGetOrHead&&gm&&guides[gm[1]])return send(res,200,guidePage(gm[1],guides[gm[1]]),{},req.method);const lm=p.match(/^\/([^/]+)\/$/);if(isGetOrHead&&lm&&legal[lm[1]])return send(res,200,legalPage(lm[1],legal[lm[1]]),{},req.method);const pm=p.match(/^\/process\/([^/]+)$/);if(req.method==='POST'&&pm&&toolBySlug.has(pm[1])){const ip=req.socket.remoteAddress||'unknown';if(!allowProcess(ip))return send(res,429,layout({title:'Too Many Requests',desc:'Rate limit reached.',noindex:true,body:`<div class="result"><h1>Too many requests</h1><p>Please try again later.</p></div>`}),{'retry-after':'600','x-robots-tag':'noindex'});return await handleProcess(req,res,toolBySlug.get(pm[1]));}const dm=p.match(/^\/download\/([^/]+)$/);if(isGetOrHead&&dm)return await handleDownload(req,res,dm[1],url);if(p.startsWith('/process/')||p.startsWith('/result/')||p.startsWith('/download/'))return send(res,404,notFound(),{'x-robots-tag':'noindex, nofollow, noarchive','cache-control':'no-store'},req.method);return send(res,404,notFound(),{},req.method);}catch(e){send(res,500,layout({title:'Server Error',desc:'A server error occurred.',noindex:true,body:`<div class="result"><div class="ok">⚠️</div><h1>Something went wrong</h1><p>Please try again.</p></div>`}),{},req.method);}});
server.listen(PORT,()=>{console.log(`${SITE_NAME} running at ${SITE_URL} on port ${PORT}`);console.log(`Tools: ${tools.length}. AdSense configured: ${ADS_CONFIGURED?'yes':'no (safe default)'}`);if(!RUNTIME_READY)console.error('WARNING: converter runtime incomplete:',JSON.stringify(RUNTIME_STATUS));});

